# ---------- structural math ----------
def ema_forecast(E0, S, b0, dn, alpha, H):
    S = min(S, 1.0)
    return S - (S - E0) * math.exp(-alpha * (dn - H * math.log((H + b0 + dn) / (H + b0))))

def gate_vector(ema, burn, theta, h):
    w = {i: ema[i] * (1 - min(burn[i], 1.0)) for i in ema}
    Z = sum(w.values()); b = {i: w[i] / Z for i in w}
    g = {i: (b[i] / (1 + (theta / b[i]) ** h) if b[i] > 0 else 0.0) for i in b}
    return b, g, Z

def project_emission(ctx, i, ema_i=None, enabled=None):
    ema = dict(ctx.ema); ema[i] = ema_i if ema_i is not None else ema[i]
    b, g, Z = gate_vector(ema, ctx.burn, ctx.theta, ctx.h)
    en = ctx.enabled if enabled is None else {**ctx.enabled, i: enabled}
    S_en = sum(g[j] for j in g if en[j])
    E_day = 0.5 * 7200 * g[i] / S_en if en[i] else 0.0       # final_i renormalised over enabled
    cap_day = ctx.rp[i] * ctx.alpha_em * ctx.spot[i] * 7200
    tao_in = min(E_day, cap_day); chain_buy = E_day - tao_in
    return E_day, tao_in, chain_buy, b[i] / ctx.theta

def sell_overhang(ctx, i):
    mint = 7200 * ctx.alpha_em
    owner = OWNER_CUT * (0 if ctx.autolock[i] else 1) * mint
    miner = MINER_SH * (1 - min(ctx.burn[i], 1.0)) * mint
    basket = P.c_claim * ctx.basket_E[i]
    S_alpha = P.f_o * owner + P.f_m * miner + basket
    return S_alpha, S_alpha * ctx.sell_price(i, S_alpha)

def svs_struct(ctx, i):
    E, tao_in, cb, _ = project_emission(ctx, i)
    _, S_tao = sell_overhang(ctx, i)
    return (cb + P.kappa_d * tao_in) / max(S_tao, 1e-9)

def y_hat_avg(ctx, g, hk, size_alpha, h_hold):
    A = ctx.A_earn[g.netuid]; vals = []
    for d in range(1, h_hold + 1):
        rp = ctx.rp_at(g.netuid, d)
        A_d = A + P.kappa_e * max(ctx.phi_ewma[g.netuid], 0) * ctx.T[g.netuid] * d / ctx.spot[g.netuid] + size_alpha
        vals.append(2952 * (1 - rp) * (1 - hk.take) * (1 - hk.ck_take) / A_d)
    return sum(vals) / len(vals)

def expected_return(ctx, g, hk, size_tao):
    T = ctx.T[g.netuid]; d = size_tao / T; h = P.h_hold
    c_rt = 2 * d / (1 + d) + 2 * FEE + 0.00186 / max(size_tao, 1e-9)
    S_now, _ = sell_overhang(ctx, g.netuid)
    S_mid = ctx.sell_alpha_at(g.netuid, h / 2)                # basket ODE
    headwind = 2 * ctx.spot[g.netuid] * (S_mid - S_now) / T
    y = y_hat_avg(ctx, g, hk, size_tao / ctx.spot[g.netuid], h)
    mu = 2 * P.lam * ctx.phi_ewma[g.netuid] + y - headwind - c_rt / h
    G = h * (mu + c_rt / h)
    return mu, G

# ---------- LCW decision ----------
def lcw_decision(g, ctx):
    s = ctx.snap(g.netuid); age = s.block - g.start_blk; why = []
    if g.flags & {'SEED_ANOMALY'}: why.append('SEED')
    if not (P.min_age <= age <= P.max_entry_age): why.append('AGE')
    if not (P.pool_min <= s.T <= P.pool_max): why.append('POOL')
    if not (P.px_lo <= s.spot / g.spot0 <= P.px_hi): why.append('PX')
    m = ctx.metrics.get(g)
    if m.mb2 > P.mb_max: why.append('BURN')
    if m.n_miners < P.miners_min or m.miner_ck < P.miner_ck_min or m.miner_top1 > P.top1_max or m.n_permit_ck < P.permit_ck_min: why.append('MINERS')
    if not (m.autolock or (m.owner_sell_ratio_7d <= P.owner_ratio_max and m.owner_tao_out_24h <= P.owner_out_max * s.T)): why.append('OWNER')
    hk = best_hotkey(ctx, g)                                  # argmax marginal net yield, realised dI/I>0 for >=2 epochs
    if hk is None or hk.y_net < P.y_net_min: why.append('YIELD')
    if ctx.phi_ewma[g.netuid] < P.phi_min or ctx.phi_6h[g.netuid] < 0: why.append('FLOW')
    size = size_order(ctx, g, s, hk)
    if size < P.min_order: why.append('SIZE')
    else:
        mu, G = expected_return(ctx, g, hk, size)
        if mu < P.mu_min or G - 2 * FEE < P.G_min: why.append('EDGE')
    if ctx.halted(): why.append('REGIME')
    if ctx.n_launch_pos() >= P.max_conc or ctx.sleeve_used() >= P.sleeve_cap * ctx.nav: why.append('CAP')
    if why: return None, why
    limit = math.ceil(s.spot_rao * (1 + P.limit_buf)); assert limit > s.spot_rao
    return Order('AddStakeLimit', hotkey=hk.ss58, netuid=g.netuid, tao=size / P.tranches, limit_price_rao=limit,
                 allow_partial=False, shielded=True, proxy='Staking', tranche_gap=P.tranche_gap, tag='LCW'), []

def size_order(ctx, g, s, hk):
    f = 2 * FEE
    G0 = 4 * P.G_min                                          # provisional gross for d_opt; refined after first pass
    mu, G = expected_return(ctx, g, hk, 0.5 * P.max_frac_pool * s.T)
    d_opt = s.T * max(G - f, 0) / 4
    d_exit = s.T * P.exit_slip / (1 - P.exit_slip)
    d_pool = P.max_frac_pool * s.T
    d_flow = P.participation * max(ctx.demand_day[g.netuid], 0)
    d_nav = min(P.pos_nav_cap * ctx.nav, P.sleeve_cap * ctx.nav - ctx.sleeve_used())
    return min(d_opt, d_exit, d_pool, d_flow, d_nav)

# ---------- exits ----------
def check_exits(g, b, ctx):
    s = ctx.snap(g.netuid); p = g.held; m = ctx.metrics.get(g)
    v = ctx.sim_sell_value(g.netuid, p.alpha_total())         # executable value incl. dividend alpha
    p.peak = max(p.peak, v)
    reasons = []
    if ctx.spec_changed() or ctx.safe_mode(): reasons.append('X1')
    if m.owner_dump() or m.owner_lock_decay or m.owner_changed: reasons.append('X2')
    if m.mb2 > P.mb_exit or m.n_miners < 4 or not ctx.hotkey_ok(p.hotkey, g.netuid): reasons.append('X3')   # try move_stake first
    if v <= (1 - P.initial_stop) * p.cost or v <= (1 - P.trail_stop) * p.peak: reasons.append('X4')
    if ctx.phi_6h[g.netuid] <= P.flow_exit * s.T or (ctx.epoch_age(g) > 5 and ctx.phi_neg_epochs(g) >= 2): reasons.append('X5')
    if ctx.y_real(p.hotkey, g.netuid, 2) < P.y_exit_min and ctx.mu_hat(g) < 0: reasons.append('X6')
    if b - p.entry_blk >= P.max_hold or b - g.reg_blk >= P.hard_exit_reg_age: reasons.append('X7')
    if reasons:
        if reasons == ['X3'] and ctx.alt_hotkey(g) is not None: ctx.emit(MoveStake(p.hotkey, ctx.alt_hotkey(g), g.netuid, 'all'))
        else: exit_now(g, ','.join(reasons), ctx)

def exit_now(g, why, ctx):
    s = ctx.snap(g.netuid)
    limit = math.floor(s.spot_rao * (1 - P.exit_slip))
    ctx.emit(Order('RemoveStakeLimit', hotkey=g.held.hotkey, netuid=g.netuid, alpha='all',
                   limit_price_rao=limit, allow_partial=False, shielded=True, proxy='Staking',
                   fallback=[dict(allow_partial=True, limit=floor(s.spot_rao*(1-2*P.exit_slip)))], tag='EXIT:' + why))

# ---------- shadow modules ----------
def l2_shadow(g, latency, ctx):                                # paper only; edge-vs-latency curve
    for k in (2, 3, 4, 6):
        ctx.paper.schedule_buy(g.netuid, tao=0.003 * g.lock / 1e9, fill_block=g.start_blk + k,
                               limit=g.spot0 * 1.03, exits=dict(tp=0.06, sl=0.03, t=1800), tag=f'L2_k{k}')

def gatekeeper_flags(netuid, ctx):                             # consumed by every other strategy
    g = book.get(netuid); f = set()
    if g is None: return f
    if g.start_blk is None: f.add('UNSTARTED')
    if ctx.block - g.reg_blk < ctx.immunity: f.add('YOUNG_IMMUNE')
    if g.start_blk and ctx.block - g.start_blk < 72_000: f.add('EMA_WARMING')
    if ctx.bar_ratio(netuid) < 0.4: f.add('GATE_STARVED')
    if svs_struct(ctx, netuid) < 0.10 and ctx.phi_7d[netuid] <= 0: f.add('DILUTED')
    if not ctx.autolock[netuid]: f.add('OWNER_LIQUID')
    if ctx.burn[netuid] > 0.60: f.add('BURNING')
    if not ctx.enabled[netuid]: f.add('EMISSION_OFF')
    if ctx.reg_clock.hazard_p24() > 0.25: f.add('REG_CLOCK_HOT')
