from enum import IntEnum
class Mode(IntEnum): NORMAL=0; CAUTION=1; EXITS_ONLY=2; FROZEN=3
FEE_BUY, FEE_SELL, F = 0.00103, 0.00084, lambda ch, n: ch.fee_rate[n] / 65535
INF = 10**12

def on_new_head(ch):
    H.update(ch)                                   # stall, finality, endpoint lag, staleness, SafeMode, spec
