# ---------- (1) prune engine ----------
def candidates(ch, t): return [n for n in ch.added if n != 0 and t >= ch.reg_at[n] + ch.immunity]
def prune_target(ch, t):
    c = candidates(ch, t); return min(c, key=lambda n: (ch.ema[n], ch.reg_at[n])) if c else None
def prune_rank(ch, n):
    c = sorted(candidates(ch, ch.block), key=lambda j: (ch.ema[j], ch.reg_at[j]))
    return c.index(n) + 1 if n in c else None
def ema_a(ch, n, t):
    if not (ch.first_emission[n] and ch.subtoken[n] and ch.reg_allowed[n]): return 0.0   # EMA frozen
    b = t - (ch.first_emission[n] - 1); return ch.moving_alpha * b / (b + ch.ema_halving[n])
def proj(E, s, a, dt): return s + (E - s) * (1 - a) ** dt
def t_star(ch, k, s_k, horizon, step=10):
    L = ladder_set(ch, horizon) | {k}
    for dt in range(0, horizon + step, step):
        t = ch.block + dt; cand = [j for j in L if t >= ch.reg_at[j] + ch.immunity]
        if k not in cand: continue
        v = {j: (proj(ch.ema[j], min(ch.spot[j], 1.0), ema_a(ch, j, t), dt), ch.reg_at[j]) for j in cand if j != k}
        v[k] = (proj(ch.ema[k], min(s_k, 1.0), ema_a(ch, k, t), dt), ch.reg_at[k])
        if min(v, key=v.get) == k: return dt
    return INF
def prune_possible(ch): return ch.n_nonroot + ch.cleanup_queue_len >= ch.subnet_limit
def window_open_at(ch): return ch.last_rl_02 + ch.network_rate_limit
def cost_ratio(ch, t):
    I_eff = ch.lock_reduction_interval * ch.block_emission_tao
    return max(ch.min_lock / ch.last_lock_cost, 2 - (t - ch.last_rl_02) / I_eff)
CDF_R = [(1.462, .09), (1.253, .19), (1.132, .31), (1.045, .50), (0.958, .72), (0.872, .84), (0.767, .94), (0.266, 1.0)]
def survival(ch, t):                               # P(no registration by block t | none since last_rl_02)
    d = t - ch.last_rl_02
    if d < ch.network_rate_limit or not prune_possible(ch): return 1.0
    r = cost_ratio(ch, t); p_open = P.P_OPEN_HOT if S.hot_market else P.P_OPEN
    F_emp = interp_desc(r, [(1.75, p_open)] + CDF_R)          # piecewise-linear in r (r decreasing over time)
    F_pri = 1 - exp(-(d - ch.network_rate_limit) / 43200)
    Sv = 1 - (32 * F_emp + P.N0 * F_pri) / (32 + P.N0)
    if r <= 1.045: Sv = min(Sv, S_at_median(ch) * exp(-P.LAMBDA_FLOOR * (t - t_at_median(ch))))
    return max(Sv, 1e-9)
def p_reg(ch, t0, t1): return 1 - survival(ch, t1) / survival(ch, t0)

def p_prune_mc(ch, horizons, step=60):             # vectorised in numpy in production
    L = sorted(ladder_set(ch, max(horizons)) | S.book.held()); n = P.N_PATHS
    E, s = init_paths(ch, L, n); alive = ones((n, len(L)), bool); last = full(n, ch.last_rl_02)
    pruned_at = full((n, len(L)), INF)
    for i in range(1, max(horizons) // step + 1):
        t = ch.block + i * step
        s *= exp(sig(L) * sqrt(step / 7200) * (sqrt(P.RHO) * randn(n, 1) + sqrt(1 - P.RHO) * randn(n, len(L)))
                 + (rand(n, len(L)) < P.JUMP_P * step / 7200) * log(1 + P.JUMP_SIZE))
        E = s + (E - s) * (1 - a_vec(ch, L, t)) ** step
        cand = alive & immune_over(ch, L, t)
        reg = rand(n) < p_reg_paths(ch, last, t - step, t)          # per-path windows (reset after each registration)
        tgt = masked_argmin(E, cand, tiebreak=reg_at(L))
        hit = reg & (tgt >= 0)
        pruned_at[hit, tgt[hit]] = t; alive[hit, tgt[hit]] = False; last[reg] = t
    return [{k: mean(pruned_at[:, j] <= ch.block + h) for j, k in enumerate(L)} for h in horizons]

def recovery_ratio(ch, k):
    x, T, E = ch.alpha_in[k], ch.tao[k], ch.escrow[k]; Sk, Pk = ch.total_alpha_staked[k], ch.protocol_alpha[k]
    T_after = T * (x / (x + E)) ** (ch.w_base[k] / ch.w_quote[k])            # baskets sold first
    denom = (Sk - E) + Pk + ((x + E) if ch.reg_at[k] > ch.tao_in_refund_block else 0)
    return clamp(T_after / denom / ch.spot[k], 0.0, 1.0) if denom > 0 else P.R_DEFAULT

def unwind_blocks(ch, k, mode):
    single = P.L_EXEC * (1 + P.RETRIES)                                        # 3*(1+2) = 9
    if mode in ('EMERGENCY', 'URGENT'): return single
    V, T = S.book.value(k, ch), ch.tao[k]; V_tr = T * P.S_TR / (1 - P.S_TR); rho = ch.excess_tao[k]
    if V <= V_tr or rho <= 0: return single                                    # CPMM path independence
    n_tr = ceil(V / V_tr); w = clamp(ceil(V_tr / rho), 10, 600)
    return n_tr * (P.L_EXEC + w) + P.RETRIES * P.L_EXEC

def s_emerg(R): return clamp(0.5 * (1 - R), 0.05, 0.25)

# ---------- (1)+(2) forced exits ----------
def risk_exits(ch, R):
    out, W, pp = {}, window_open_at(ch), prune_possible(ch)
    for k in S.book.held():
        Rk = R.R.get(k, P.R_DEFAULT); U = unwind_blocks(ch, k, 'EMERGENCY')
        if S.book.generation(k) != (k, ch.reg_at.get(k)): out[k] = Exit('DISSOLVED'); continue
        if pp and ch.block + U + P.M_A >= W and (k == R.target or R.tA[k] <= U + P.M_A):
            out[k] = Exit('EMERGENCY', 'prune_A', s_emerg(Rk)); continue
        if pp and ch.block + P.H_B >= W and R.p24.get(k, 0) * (1 - Rk) >= P.PI_B:
            out[k] = Exit('URGENT', 'prune_B', P.S_URGENT); continue
        rk = prune_rank(ch, k)
        if pp and rk is not None and rk <= P.K_BOTTOM and cost_ratio(ch, ch.block) <= P.R_BACKSTOP:
            out[k] = Exit('URGENT', 'prune_backstop', P.S_URGENT); continue
        if S.emission_flipped_off(k) and not S.book.entered_while_disabled(k):
            out[k] = Exit('URGENT', 'emission_off', P.S_URGENT); continue
        if S.book.launch_only(k) and (days_since_start(ch, k) > P.LAUNCH_HARD_STOP or
                                      (not ch.emission_enabled[k] and days_since_start(ch, k) > P.ENABLE_WAIT_MAX)):
            out[k] = Exit('NORMAL', 'launch_stop', P.S_EXIT_ENTRY); continue
        for s in S.book.sleeves_holding(k):
            if s.requires_bid and R.gate[k].dropout: out.setdefault(k, Exit('NORMAL', 'gate_dropout', P.S_EXIT_ENTRY, sleeves={s}))
    return out

def gate_and_drift(ch):
    elig = [n for n in ch.added if n and ch.first_emission[n] and ch.subtoken[n] and ch.reg_allowed[n]]
    tot = sum(ch.ema[n] for n in elig); b = {n: ch.ema[n] / tot * (1 - min(ch.miner_burned[n], 1)) for n in elig}
    Z = sum(b.values()) or 1; theta, h = ch.gate_bar, (ch.gate_exp or 3); out = {}
    for n in elig:
        bn = b[n] / Z; g = 1 / (1 + (theta / bn) ** h) if bn > 0 else 0.0
        p, T = ch.spot[n], ch.tao[n]
        liquid = 7200 * ch.alpha_out_em[n] * (0.18 * (0 if ch.owner_autolock[n] else 1) + 0.41 * (1 - min(ch.miner_burned[n], 1)))
        D = (P.LAMBDA_SELL * liquid * p + P.C_CLAIM * ch.escrow[n] * p - 7200 * ch.excess_tao[n]) / T
        y = S.val_yield.get(n) or 7200 * ch.alpha_out_em[n] * 0.41 * (1 - ch.root_prop[n]) / ch.a_earn[n] * (1 - P.ASSUMED_TAKE)
        out[n] = Gate(g=g, D=D, TRD=y - 2 * D, dropout=S.g_hist[n].fell(from_=0.5, to=0.1, within=3))
    return out

# ---------- (3) caps ----------
def vmax_exit(ch, n, s, T):
    if abs(ch.w_quote[n] - 0.5) < 0.01: return T * s / (1 - s)
    return bisect(lambda a: exit_shortfall_pool(ch, n, a, T) - s) * ch.spot[n]
def position_caps(ch, R):
    caps, no_inc = {}, set()
    for n in universe(ch):
        Tst = min(ch.tao[n], S.tao_min_3d[n]) * (1 - P.D_T); gt = R.gate.get(n)
        m_gate = 1.0 if gt.g >= P.G_FULL else (0.5 if gt.g >= P.G_LOW else 0.25)
        m_esc = clamp(1 - ch.escrow[n] / ch.alpha_in[n], 0.5, 1.0); m_trd = 0.5 if gt.TRD < P.TRD_HALF else 1.0
        caps[n] = min(vmax_exit(ch, n, P.S_EXIT_ENTRY, Tst) * m_gate * m_esc * m_trd, P.NU_MAX * S.nav_liq)
        if not entry_allowed(ch, n, R): no_inc.add(n)
    for n in S.book.held():
        if exit_shortfall(ch, n, S.book.alpha(n)) > P.S_EXIT_HOLD_MAX:
            caps[n] = min(caps.get(n, 0.0), vmax_exit(ch, n, P.S_EXIT_ENTRY, ch.tao[n]))
    return caps, no_inc
def exit_shortfall(ch, n, alpha):
    out = simulate_sell(pool_of(ch, n), alpha)[0]; return 1 - (out - FEE_SELL) / (alpha * ch.spot[n])
def entry_allowed(ch, n, R, sleeve=None):      # universe_filter A-G + prune/flow gates (see entry_rules)
    if not base_eligible(ch, n, sleeve): return False
    if prune_possible(ch):
        if not ch.immune(n):
            if prune_rank(ch, n) <= P.K_ENTRY_HARD or ch.ema[n] < ch.ema[R.target] * (1 + P.G_ENTRY): return False
            if R.p7d.get(n, 0) * (1 - R.R.get(n, P.R_DEFAULT)) > P.PI_ENTRY_7D: return False
        elif immunity_ends_within(ch, n, 50400) and projected_rank_at_expiry(ch, n) <= P.K_ENTRY_HARD: return False
    if R.gate[n].TRD < P.TRD_BAN and not (sleeve and sleeve.bid_independent): return False
    return not in_cooldown(n) and choose_hotkey(ch, n, 0.0) is not None

# ---------- (4)+(5) allocator ----------
def budgets(mode_dd_mult):
    if P.ALLOC_MODE == 'fixed' or min(s.paper_days for s in S.sleeves) < 60: b = dict(P.B_FIXED)
    else:
        inv = {s: 1 / sqrt(0.5 * s.var60 + 0.5 * P.SIGMA_PRIOR[s] ** 2) for s in S.sleeves}
        b = {s: (1 - P.SHRINK) * v / sum(inv.values()) + P.SHRINK * P.B_FIXED[s] for s, v in inv.items()}
    b = normalize({s: clamp(v, P.B_MIN, P.B_MAX[s]) for s, v in b.items()})
    G_eff = P.G_MAX * mode_dd_mult
    return {s: S.nav_liq * G_eff * b[s] * {'ACTIVE': 1, 'REDUCED': .5}.get(s.state, 0) for s in S.sleeves}, G_eff
def allocator(ch, caps, no_inc, forced, mode):
    B, G_eff = budgets(H.dd_mult()); contrib = defaultdict(dict)
    for s in S.sleeves:
        for n, (w, alpha_h, conf) in s.targets().items():          # long-only weights, sum <= 1
            x = B[s] * w
            if alpha_h is not None: x = min(x, ch.tao[n] * max(alpha_h - 2 * F(ch, n), 0) / 4)   # V*
            held = S.ledger[s].value(n, ch)
            if mode >= Mode.CAUTION or n in no_inc or not entry_allowed(ch, n, S.risk, s): x = min(x, held)
            contrib[n][s] = (x, conf)
    for n in list(contrib):
        if n in forced and forced[n].kind != 'NORMAL': contrib[n] = {s: (0.0, c) for s, (_, c) in contrib[n].items()}
        elif n in forced: contrib[n] = {s: ((0.0 if s in forced[n].sleeves_or_all() else x), c) for s, (x, c) in contrib[n].items()}
        tot = sum(x for x, _ in contrib[n].values())
        if tot > caps.get(n, 0.0): contrib[n] = fit_to_cap(contrib[n], caps.get(n, 0.0), S.ledger, 'holdings_first_then_conf')
    contrib = enforce_max_positions(contrib, min(P.N_MAX, int(G_eff * S.nav_liq // (4 * P.V_MIN))))
    contrib = enforce_bucket_caps(contrib, ch, ladder=.15, owner_cluster=.20, young=.10, sum_exit_cost=.02)
    contrib = scale_to_gross(contrib, G_eff * S.nav_liq)
    S.virtual_cross(contrib, ch)        # sleeves trade with each other at spot; only net hits the pool
    return {n: sum(x for x, _ in c.values()) for n, c in contrib.items()}

def evaluate_sleeve_kills():                     # daily; paper and live separately; also un-netted P&L
    for s in S.sleeves:
        m = s.metrics()
        if (m.dd >= P.KS_SUSPEND_DD or m.mean45 < s.bt_boot_q05_45d or m.cost_ratio20 > 2.5
                or s.falsification_breached()): s.state = 'SUSPENDED'
        elif m.dd >= P.KS_REDUCE_DD or m.cost_ratio20 > 1.5 or m.turnover7 > 2 * s.bt_turnover7:
            s.state = max_state(s.state, 'REDUCED')
        elif s.state == 'SUSPENDED' and m.paper_days_since >= 30 and m.paper_mean30 > 0 and m.paper_dd30 < .05:
            s.state = 'REDUCED'
        elif s.state == 'REDUCED' and m.days_in_state >= 30 and m.dd < P.KS_REDUCE_DD / 2: s.state = 'ACTIVE'

# ---------- (6) kill switches ----------
def mode():                                      # method of health object H
    if H.key_alarm or H.safe_mode or not H.head_endpoint_ok: return Mode.FROZEN
    if LIVE and H.tx_version_changed: return Mode.FROZEN
    m = Mode.NORMAL
    if H.spec != S.validated_spec: m = max(m, Mode.CAUTION if H.smoke_ok else Mode.EXITS_ONLY)
    if H.secs_since_block > P.STALL_HALT: m = max(m, Mode.EXITS_ONLY)
    elif H.secs_since_block > P.STALL_WARN: m = max(m, Mode.CAUTION)
    if H.finality_lag > P.FINALITY_CAUTION or H.prune_input_age > P.STALE_PRUNE or H.healthy_endpoints < 2: m = max(m, Mode.CAUTION)
    if H.daily_loss >= P.DAILY_LOSS or H.dd30 >= P.DD_HARD or H.fail_burst_global: m = max(m, Mode.CAUTION)
    if H.delegate_min_bal < 0.05: m = max(m, Mode.EXITS_ONLY)
    elif H.delegate_min_bal < 0.15: m = max(m, Mode.CAUTION)
    return m
def dd_mult(): return (0.5 if H.dd30 >= P.DD_SOFT else 1) * (0.5 if H.dd30 >= P.DD_HARD else 1)
def shield_ok(): return H.finality_lag <= P.FINALITY_SHIELD_PAUSE and H.submit_node_at_head
def reconcile(ch):
    for key, a in onchain_stakes(ch, REAL).items():
        exp = S.book.expected_alpha(key, ch)      # own matched fills + epoch accrual at LastEpochBlock(n)
        if a < exp * (1 - 1e-6) - 2e-9 or a > exp * (1 + 3 * S.exp_epoch_yield(key)) + 2e-9: alarm('STAKE_DELTA', key)
    if set(onchain_stakes(ch, REAL)) - S.book.keys(): alarm('UNKNOWN_POSITION')
    for d in DELEGATES:
        if ch.nonce[d] != S.nonce_expected[d]: alarm('DELEGATE_NONCE', d)
    if ch.proxies[REAL] != S.proxies_expected or ch.coldkey_swap_scheduled[REAL] or ch.announcements[REAL]: alarm('ACCOUNT_CHANGE')
    if foreign_stake_events(ch, REAL) or fee_paid_with_alpha(ch, REAL): alarm('FOREIGN_EVENT')
def alarm(kind, *a): H.key_alarm = True; notify_user(kind, a, advice='revoke the Staking proxy from the coldkey signer')

# ---------- (7) validator + dust ----------
def choose_hotkey(ch, n, our_alpha):
    best = None
    for h in dividend_keys(ch, n, epochs=3):                                   # AlphaDividendsPerSubnet(n,.)
        if ch.delegates[h] / 65535 > P.TAKE_MAX or take_raised_within(h, 216000): continue
        if our_alpha / max(ch.total_hotkey_alpha[h, n], 1e-9) > P.Q_MAX: continue
        if stake_rank(ch, n, h) > P.PERMIT_RANK_FRAC * ch.max_allowed_validators[n]: continue
        y = median(dlnI(h, n, P.K_EPOCHS)) * 7200 / ch.tempo[n]
        cand = ((y, ch.total_hotkey_alpha[h, n]), h); best = max(best, cand) if best else cand
    return best and best[1]
def maybe_switch_validator(ch, n):
    cur = S.book.hotkey(n); new = choose_hotkey(ch, n, S.book.alpha(n))
    if new is None or new == cur: return
    yc, yn = S.val_yield_h(cur, n), S.val_yield_h(new, n)
    if fails_filters(cur, epochs=2) or take_jump(cur) > 0.05 or \
       (yn - yc > max(0.0002, 0.10 * yc) and S.persisted(new, 2) and (yn - yc) * 30 * S.book.value(n, ch) > 3 * FEE_BUY):
        submit(MoveStake(cur, n, new, n, amount=U64_MAX))                   # same subnet: no swap fee
def apply_dust_rule(ch, n, alpha_sell):
    rem_tao = (S.book.alpha(n) - alpha_sell) * ch.spot[n]
    return S.book.alpha(n) if 0 < rem_tao < P.REMAINDER_MIN else alpha_sell  # full exit instead of dust

# ---------- (8) order planning ----------
def beta(n, purpose):
    r2 = abs_dlog_2blk(n, lookback=1800, exclude_own=True)
    return clamp(quantile(r2, .95), .001, P.BETA_MAX_ENTRY) if purpose == 'ENTRY' else clamp(quantile(r2, .99), .0025, .05)
def plan_entry(ch, n, tao):
    pool, f = pool_of(ch, n), F(ch, n)
    tao = min(tao, pool.tao * P.S_AVG_ENTRY / (1 - P.S_AVG_ENTRY) / (1 - f))      # avg-slippage cap (w=.5)
    if tao < P.V_MIN or tao * (1 - f) < 0.002: return None
    p_marg = pool.spot() * (1 + tao * (1 - f) / pool.tao) ** (1 / pool.w_base)   # marginal after fill, no drift
    limit = ceil(p_marg * (1 + beta(n, 'ENTRY')) * 1e9); assert limit > pool.spot_rao()
    assert max_buy_to_limit(pool, limit / 1e9) >= tao
    q = rt_sim_swap_tao_for_alpha(n, tao, block=ch.block)
    if q.alpha == 0 or abs(q.alpha / simulate_buy(pool, tao)[0] - 1) > 1e-5: return None
    return Order(n, 'add_stake_limit', amount=tao, limit=limit, allow_partial=True, purpose='ENTRY',
                 ref_spot=pool.spot(), decision_block=ch.block, hotkey=choose_hotkey(ch, n, 0.0) or S.book.hotkey(n))
def plan_exit(ch, n, alpha, kind, s_budget):
    pool, f = pool_of(ch, n), F(ch, n); held = S.book.alpha(n)
    if kind in ('EMERGENCY', 'URGENT'):
        return Order(n, 'remove_stake_limit', amount=held, limit=floor(pool.spot() * (1 - s_budget) ** 2 * 1e9),
                     allow_partial=True, purpose=kind, s_budget=s_budget)
    alpha = apply_dust_rule(ch, n, alpha); full = alpha >= held
    if not full: alpha = min(alpha, pool.alpha * P.S_AVG_EXIT / (1 - P.S_AVG_EXIT) / (1 - f))
    if not full and simulate_sell(pool, alpha, partial_remaining=True)[0] < 0.002: return None
    p_marg = pool.spot() * (1 + alpha * (1 - f) / pool.alpha) ** (-1 / pool.w_quote)
    limit = floor(p_marg * (1 - beta(n, 'EXIT')) * 1e9); assert limit < pool.spot_rao()
    if full: return Order(n, 'remove_stake_full_limit', limit=limit, purpose='EXIT')     # fill-or-kill by nature
    return Order(n, 'remove_stake_limit', amount=alpha, limit=limit, allow_partial=True, purpose='TRIM')
def plan_orders(ch, targets, forced, mode):
    orders = [plan_exit(ch, k, S.book.alpha(k), e.kind, e.s_budget) for k, e in
              sorted(forced.items(), key=lambda kv: -urgency(ch, *kv)) if e.kind != 'DISSOLVED']
    if mode <= Mode.CAUTION:
        for n, tgt in targets.items():                 # sells first (cash), then buys; no batching via Staking proxy
            d = tgt - S.book.value(n, ch)
            if d < 0 and -d >= max(P.V_MIN, P.BAND * S.book.value(n, ch)):
                orders.append(plan_exit(ch, n, -d / ch.spot[n], 'NORMAL', P.S_AVG_EXIT))
        if mode == Mode.NORMAL:
            for n, tgt in targets.items():
                d = tgt - S.book.value(n, ch)
                if d > 0 and d >= max(P.V_MIN, P.BAND * tgt) and worth_it(ch, n, d): orders.append(plan_entry(ch, n, d))
    return [o for o in orders if o and one_inflight_per_netuid(o)]
def dispatch(orders, ch):
    for o in orders:
        d = free_delegate()                            # not nonce-locked; 1 in-flight shielded order each
        if d is None or not H.submit_node_at_head or ch.block != H.head: break       # re-plan on the next head
        if shield_ok(): EXEC.submit_shielded(o, d, period=8)                         # paper: N+2 simulator
        elif o.purpose in ('EMERGENCY', 'URGENT'): EXEC.submit_unshielded(o, d, period=16)   # MEV risk < prune risk
def on_order_result(o, res, ch):
    if res.status == 'MISSED': lock_delegate(o.delegate, o.era_end); return requeue(replan(o, ch))
    if res.err == 'SubnetNotExists': return mark_dissolved(o.netuid)
    book_from_post_state(o, ch); abnormal_fill_check(o, res, ch)
    resid = residual_after(o, ch)
    if res.status == 'FILLED' and resid <= 0: return
    if o.purpose == 'ENTRY':
        drift = ch.spot[o.netuid] / o.ref_spot - 1
        if o.chase < P.K_CHASE and drift < P.CHI_MAX and resid >= P.V_MIN:
            return requeue(replan(o, ch, beta_mult=1.5, chase=o.chase + 1))
        return notify_sleeve(o, 'abandoned')
    if o.call == 'remove_stake_full_limit' and res.err == 'SlippageTooHigh':
        return requeue(o.replace(call='remove_stake_limit', amount=S.book.alpha(o.netuid), allow_partial=True))
    if o.purpose in ('EMERGENCY', 'URGENT'):
        return requeue(replan(o, ch, s_budget=min(o.s_budget * 1.5, s_emerg(S.risk.R.get(o.netuid, P.R_DEFAULT)))))
    if resid * ch.spot[o.netuid] >= P.V_MIN: requeue(replan(o, ch))
